WITH valid_transactions AS (SELECT * FROM transactions WHERE (amount <= 3200 AND amount BETWEEN 1300 AND 3800) OR account_id = 21), transactions_stats AS (SELECT txn_type, ROUND(STDDEV(amount), 2) AS stddev_amount, COUNT(amount) AS amount_count FROM valid_transactions GROUP BY txn_type) SELECT * FROM transactions_stats WHERE stddev_amount < 73 ORDER BY amount_count ASC, txn_type ASC LIMIT 10;
